    internal static void Run()
    {
        var failures = new List<string>();
        foreach(var c in Core.Concat(Guards))
        {
            try { Check(c); Console.WriteLine($"CASE {c.Name} completed"); }
            catch(Exception e) { failures.Add($"{c.Name}: {e.Message}"); }
        }
        if(failures.Count>0) throw new InvalidOperationException(string.Join("\n",failures));
        Console.WriteLine("61 fixtures (CORE8 + 53 guards) passed");
    }
    private static void Check(Case c)
    {
        using var doc=NativeDomDocument.Parse(c.Html);
        using var runtime=new StyleRuntimeInterop(800,600,1);
        runtime.Load(doc,"",c.Css);
        var count=doc.EnumerateElementHandles().Count();
        var resolved=runtime.Resolve(new int[count],800,600,1);
        // Resolve may change DOM ownership; enumerate the final handles afterwards.
        var handles=doc.EnumerateElementHandles().ToArray();
        IntPtr Node(string id)=>handles.Single(h=>doc.GetAttributes(h).Any(a=>a.Key=="id"&&a.Value==id));
        using var map=runtime.CreateResolvedStyleMap(doc);
        using var engine=new NativeLayoutInterop((_,_,_)=>c.Kind==1?(c.Col?new NativeTextMetrics(20,200,150):new NativeTextMetrics(200,20,15)):default);
        using var layout=engine.Layout(doc,map,800,600,_=>default);
        IEnumerable<NativeLayoutBox> Walk(NativeLayoutBox b){yield return b;for(int i=0;i<b.ChildCount;i++)foreach(var child in Walk(layout.GetChild(b,i)))yield return child;}
        NativeLayoutBox Box(string id)=>Walk(layout.Root).First(b=>b.Element==Node(id));
        var host=Box("host");var origin=host.ContentBox;
        float Main(NativeRect r)=>c.Col?r.Height:r.Width;
        float Cross(NativeRect r)=>c.Col?r.Width:r.Height;
        float Offset(NativeRect r)=>c.Col?r.Y-origin.Y:r.X-origin.X;
        float CrossOffset(NativeRect r)=>c.Col?r.X-origin.X:r.Y-origin.Y;
        Equal(Main(host.BorderBox),c.Main,"host main");Equal(Cross(host.BorderBox),c.Cross,"host cross");
        var hs=resolved.Styles[Array.IndexOf(handles,Node("host"))];Equal(hs.Display,4,"flex display");Equal(hs.JustifyContent,c.Justify,"justify");Equal(hs.FlexDirection,c.Col?1:0,"direction");
        if(c.Kind==0)
        {
            for(int i=0;i<c.Ids.Length;i++)
            {
                var b=Box(c.Ids[i]);var s=resolved.Styles[Array.IndexOf(handles,Node(c.Ids[i]))];Equal(s.Display,1,"item display");Equal(s.FlexShrink,c.Shrink,"shrink");
                Equal(Main(b.BorderBox),c.Sizes[i],"item main");Equal(Cross(b.BorderBox),20,"item cross");Equal(Offset(b.BorderBox),c.Offsets[i],"main offset");Equal(CrossOffset(b.BorderBox),c.Crosses[i],"cross offset");
                if(i>0)Equal(Offset(b.BorderBox)-Offset(Box(c.Ids[i-1]).BorderBox),c.Offsets[i]-c.Offsets[i-1],"separation");
            }
            if(c.Desc){var b=Box("desc");var p=Box(c.Ids[0]);Equal(b.BorderBox.X,p.ContentBox.X,"descendant x");Equal(b.BorderBox.Y,p.ContentBox.Y,"descendant y");Equal(b.BorderBox.Width,10,"descendant width");Equal(b.BorderBox.Height,10,"descendant height");}
        }
        else if(c.Kind==1)
        {
            var fragments=Walk(host).Where(b=>b.Kind==2).ToArray();Equal(fragments.Length,1,"fragment count");var f=fragments.Single();
            Equal(Offset(f.BorderBox),-50,"fragment offset");Equal(CrossOffset(f.BorderBox),0,"fragment cross offset");Equal(Main(f.BorderBox),200,"fragment main");Equal(Cross(f.BorderBox),20,"fragment cross");
            Equal(host.ChildCount,1,"one wrapper");var wrapper=layout.GetChild(host,0);Equal(wrapper.ChildCount,1,"wrapper fragment");Equal(Main(wrapper.BorderBox),200,"wrapper main");Equal(Cross(wrapper.BorderBox),20,"wrapper cross");Equal(Offset(wrapper.BorderBox),-50,"wrapper offset");
        }
        else Equal(host.ChildCount,0,"empty whitespace content/zero fragments");
    }
    private static void Equal(float actual,float expected,string field)
    {if(!float.IsFinite(actual)||MathF.Abs(actual-expected)>.01f)throw new InvalidOperationException($"{field}: actual={actual}, expected={expected}");}
